Chapter.Code:
MeshDraw draw;
draw.Mesh = meshHandle;
draw.Model = worldTransform;
draw.Material = material;

TextureHandle texture;
MeshHandle mesh;
BufferHandle buffer;

using TextureHandle =
    std::uint64_t;

using MeshHandle =
    std::uint64_t;

struct TextureHandle
{
    uint32_t Index;
    uint32_t Generation;
};

struct TextureEntry
{
    uint32_t Generation;
    NativeTexture Resource;
};

struct ResourceHandle
{
    uint32_t index;
    uint32_t generation;
};

enum class BufferUsage : uint32_t
{
    Vertex   = 1 << 0,
    Index    = 1 << 1,
    Uniform  = 1 << 2,
    Storage  = 1 << 3,
    Indirect = 1 << 4,
    CopySrc  = 1 << 5,
    CopyDst  = 1 << 6
};

struct BufferDesc
{
    uint64_t Size;
    BufferUsage Usage;

    MemoryClass Memory;

    std::string DebugName;
};

enum class MemoryClass
{
    GPUOnly,
    CPUToGPU,
    GPUToCPU
};

