Chapter.Code:
struct TextureDesc
{
    TextureDimension Dimension;

    uint32_t Width;
    uint32_t Height;
    uint32_t Depth;

    uint32_t MipLevels;
    uint32_t ArrayLayers;
    uint32_t Samples;

    PixelFormat Format;
    TextureUsage Usage;

    MemoryClass Memory;

    std::string DebugName;
};

struct SamplerDesc
{
    Filter Min;
    Filter Mag;
    Filter Mip;

    AddressMode U;
    AddressMode V;
    AddressMode W;

    float MaxAnisotropy;

    CompareFunction Comparison;
};

struct GraphicsPipelineDesc
{
    ShaderHandle Vertex;
    ShaderHandle Fragment;

    VertexLayout VertexInput;

    PrimitiveTopology Topology;

    RasterState Raster;
    DepthStencilState DepthStencil;
    BlendState Blend;

    std::vector<PixelFormat>
        ColorFormats;

    PixelFormat DepthFormat;

    uint32_t SampleCount;
};

struct RendererCapabilities
{
    bool RayTracing;
    bool MeshShaders;
    bool BindlessTextures;
    bool AsyncCompute;
    bool MemorylessAttachments;
    bool TimelineSynchronization;

    uint32_t MaxColorAttachments;
    uint32_t MaxTextureDimension2D;
};

graph.AddPass(
    "Lighting",
    {
        Read(gbufferNormal,
             ShaderRead),

        Read(gbufferDepth,
             ShaderRead),

        Write(hdrColor,
              ColorAttachment)
    },
    [] {
        EncodeLighting();
    });

for pass in compiledOrder:
    apply inferred native state changes
    execute pass callback

struct AliasClass
{
    ResourceKind Kind;

    MemoryClass Memory;

    uint64_t Size;
    uint64_t Alignment;

    uint32_t SampleCount;

    FormatCompatibilityClass FormatClass;

    ResourceUsage Usage;
};

