Chapter.Code:
digraph AetherRenderGraph {
  p0 [label="Shadow"];
  p1 [label="Geometry"];
  p2 [label="TAA"];
  p3 [label="Present"];

  p0 -> p1;
  p1 -> p2;
  p2 -> p3;
}

struct PassDesc
{
    std::string Name;

    QueueClass Queue;

    std::vector<ResourceAccess>
        Accesses;

    bool HasSideEffects = false;

    ExecuteCallback Execute;
};

struct ResourceAccess
{
    ResourceHandle Resource;

    AccessMode Access;

    ResourceUsage Usage;

    ShaderStageMask Stages;
};

struct ResourceState
{
    PipelineDomain Domain;
    AccessFlags Access;
    UsageClass Usage;
};
